package main

import (
	"bufio"
	"fmt"
	"os"
)

const MOD = 998244353
const MAXN = 50000

var fact [MAXN + 1]int
var invFact [MAXN + 1]int

func modPow(a, e int) int {
	res := 1
	for e > 0 {
		if e&1 == 1 {
			res = res * a % MOD
		}
		a = a * a % MOD
		e >>= 1
	}
	return res
}

func init() {
	fact[0] = 1
	for i := 1; i <= MAXN; i++ {
		fact[i] = fact[i-1] * i % MOD
	}
	invFact[MAXN] = modPow(fact[MAXN], MOD-2)
	for i := MAXN; i >= 1; i-- {
		invFact[i-1] = invFact[i] * i % MOD
	}
}

func C(n, k int) int {
	if k < 0 || k > n {
		return 0
	}
	return fact[n] * invFact[k] % MOD * invFact[n-k] % MOD
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(reader, &n)

	sum := 0
	for m := 1; m <= n/2; m++ {
		if (n - 2*m) % 2 != 0 {
			continue
		}
		k := (n - 2*m) / 2

		// term1 = n! / (n - 2m)!
		term1 := fact[n] * invFact[n-2*m] % MOD

		// term2 = C(m + k - 1, k)
		term2 := C(m+k-1, k)

		// term3 = k! * 2^k
		term3 := fact[k] * modPow(2, k) % MOD

		add := term1 * term2 % MOD * term3 % MOD
		sum = (sum + add) % MOD
	}

	fmt.Println(sum)
}
